using System;using System.IO;using System.Reflection;using System.Diagnostics;using System.Drawing;using System.Windows.Forms;using Microsoft.Web.WebView2.WinForms;
class PackagedSmoke{
static BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(object o,string n){return o.GetType().GetField(n,f).GetValue(o);}static void Pump(int ms){var s=Stopwatch.StartNew();while(s.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(2);}}static void Wait(Func<bool> done,string label){var s=Stopwatch.StartNew();while(!done()&&s.ElapsedMilliseconds<20000)Pump(15);if(!done())throw new Exception(label);}
static string JS(WebView2 web,string script){var t=web.CoreWebView2.ExecuteScriptAsync(script);Wait(()=>t.IsCompleted,"JavaScript timeout");return t.GetAwaiter().GetResult();}
[STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();var a=Assembly.LoadFrom(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"LumaView.exe"));
using(var video=(Form)Activator.CreateInstance(a.GetType("LumaView.VideoViewer"),new object[]{args[0],new Rectangle(0,0,1200,800)})){video.Show();Wait(()=>(bool)Get(video,"ready"),"Packaged video failed: "+((Label)Get(video,"details")).Text);Pump(600);if((double)Get(video,"position")<.2)throw new Exception("Video stalled");video.GetType().GetMethod("Toggle",f).Invoke(video,null);Pump(100);video.GetType().GetMethod("QueueSeek",f).Invoke(video,new object[]{2.0});Pump(100);Wait(()=>!(bool)Get(video,"navigating")&&Get(video,"pendingSeek")==null,"Seek timeout");if(Math.Abs((double)Get(video,"position")-2)>.1)throw new Exception("Seek position mismatch");Console.WriteLine("PASS extracted package video playback and exact seek");video.Close();}
using(var model=(Form)Activator.CreateInstance(a.GetType("LumaView.ModelViewer"),new object[]{args[1],new Rectangle(0,0,1200,800)})){model.Show();Wait(()=>(bool)Get(model,"ready"),"Packaged model failed");var web=(WebView2)Get(model,"web");JS(web,"window.selectEnvironment('forest_slope')");Wait(()=>JS(web,"window.modelState().environment.loading")=="false","Packaged HDR load timeout");if(JS(web,"window.modelState().environment.loaded")!="true"||JS(web,"window.modelState().environment.error")!="\"\"")throw new Exception("Packaged HDR failed");JS(web,"window.setEnvironment({rotation:90,background:true});window.setRenderEffects({bloom:true,outline:true})");Pump(300);if(JS(web,"document.getElementById('message').textContent")!="\"\"")throw new Exception("Rendering failed");Console.WriteLine("PASS extracted package HDR loading, rotation and effects");model.Close();}return 0;
}catch(Exception e){Console.WriteLine(e);return 1;}}
}
